    if "a" <= ch <= "z":
        natija.append(chr((a * (ord(ch) - 97) + b) % 26 + 97))
    elif "A" <= ch <= "Z":
        natija.append(chr((a * (ord(ch) - 65) + b) % 26 + 65))
    else:
        natija.append(ch)
